/**
 * Remove a student from a classroom
 */
export const removeMutation = (options?: Partial<Options<RemoveData>>): UseMutationOptions<unknown, DefaultError, Options<RemoveData>> => {
    const mutationOptions: UseMutationOptions<unknown, DefaultError, Options<RemoveData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await remove({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};
